create table if not exists consolidation_runs(id bigint generated always as identity primary key,holding_subsidiary_id bigint not null references subsidiaries,period varchar(7)not null,presentation_currency_id bigint not null references currencies,status varchar(20)not null default'BORRADOR'check(status in('BORRADOR','VALIDADO','CONVERTIDO','ELIMINADO','PROCESADO','PUBLICADO','ANULADO')),total_assets numeric(24,4)not null default 0,total_liabilities numeric(24,4)not null default 0,total_equity numeric(24,4)not null default 0,cta_oci numeric(24,4)not null default 0,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(holding_subsidiary_id,period));
create table if not exists consolidation_eliminations(id bigint generated always as identity primary key,run_id bigint not null references consolidation_runs on delete cascade,elimination_type varchar(30)not null check(elimination_type in('CXC_CXP','VENTA_GASTO','INVERSION_PATRIMONIO','CTA_OCI','MANUAL')),concept text not null,debit_account_id bigint references chart_accounts,credit_account_id bigint references chart_accounts,amount numeric(24,4)not null check(amount>0),is_automatic boolean not null default false,created_at timestamptz not null default now());
create table if not exists consolidation_worksheet(id bigint generated always as identity primary key,run_id bigint not null references consolidation_runs on delete cascade,subsidiary_id bigint not null references subsidiaries,account_id bigint not null references chart_accounts,original_balance numeric(24,4)not null,original_currency_id bigint not null references currencies,rate_type varchar(20)not null check(rate_type in('CIERRE','PROMEDIO','HISTORICA','IDENTIDAD')),applied_rate numeric(24,10)not null,translated_balance numeric(24,4)not null,elimination_debit numeric(24,4)not null default 0,elimination_credit numeric(24,4)not null default 0,final_balance numeric(24,4)not null,unique(run_id,subsidiary_id,account_id));
insert into permissions(code,module,description)values('ACC_CONSOLIDATION_RUN','Consolidación','Iniciar y ejecutar consolidaciones financieras.'),('ACC_CONSOLIDATION_PUBLISH','Consolidación','Publicar y bloquear estados consolidados.')on conflict(code)do nothing;
insert into role_permissions(role_id,permission_id)select r.role_id,p.permission_id from roles r cross join permissions p where p.code in('ACC_CONSOLIDATION_RUN','ACC_CONSOLIDATION_PUBLISH')and(r.is_system_role or lower(r.role_name)like'%admin%')on conflict do nothing;
do $$declare t regclass;begin foreach t in array array['consolidation_runs'::regclass,'consolidation_eliminations'::regclass,'consolidation_worksheet'::regclass]loop perform install_actor_audit(t);execute format('alter table %s enable row level security',t);execute format('drop policy if exists consolidation_access on %s',t);execute format('create policy consolidation_access on %s for all to authenticated using(true)with check(true)',t);end loop;end$$;

create or replace function consolidation_has_permission(code text)returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from user_roles ur join role_permissions rp using(role_id)join permissions p using(permission_id)where ur.user_id=app_user_id()and p.code=code)$$;
create or replace function consolidation_options()returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('holding',(select jsonb_build_object('id',subsidiary_id,'name',name)from subsidiaries where lower(trim(name))='stt group latin american'limit 1),'currency',(select jsonb_build_object('id',currency_id,'code',currency_code)from currencies where currency_code='USD'),'periods',coalesce((select jsonb_agg(distinct to_char(end_date,'YYYY-MM')order by to_char(end_date,'YYYY-MM')desc)from fiscal_periods),'[]'),'runs',coalesce((select jsonb_agg(jsonb_build_object('id',id,'period',period,'status',status,'assets',total_assets,'liabilities',total_liabilities,'equity',total_equity,'cta',cta_oci)order by id desc)from consolidation_runs),'[]'),'canRun',consolidation_has_permission('ACC_CONSOLIDATION_RUN'),'canPublish',consolidation_has_permission('ACC_CONSOLIDATION_PUBLISH'))$$;

create or replace function consolidation_init(p_period varchar)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare hid bigint;usd bigint;rid bigint;open_count int;rate_count int;required_count int;begin if not consolidation_has_permission('ACC_CONSOLIDATION_RUN')then raise exception'No tiene permiso para ejecutar consolidaciones.';end if;if p_period!~'^[0-9]{4}-(0[1-9]|1[0-2])$'then raise exception'Periodo inválido.';end if;select subsidiary_id into hid from subsidiaries where lower(trim(name))='stt group latin american'limit 1;select currency_id into usd from currencies where currency_code='USD';select count(*)into open_count from subsidiaries s where s.is_active and s.subsidiary_id<>hid and not exists(select 1 from fiscal_periods f where f.subsidiary_id=s.subsidiary_id and to_char(f.end_date,'YYYY-MM')=p_period and f.is_closed);select count(*)into required_count from subsidiaries where is_active and subsidiary_id<>hid and currency_id<>usd;select count(distinct source_subsidiary_id)into rate_count from consolidated_exchange_rates where holding_subsidiary_id=hid and period=p_period and to_currency_id=usd;if open_count>0 or rate_count<required_count then return jsonb_build_object('ready',false,'openSubsidiaries',open_count,'missingRates',required_count-rate_count);end if;insert into consolidation_runs(holding_subsidiary_id,period,presentation_currency_id,status)values(hid,p_period,usd,'VALIDADO')on conflict(holding_subsidiary_id,period)do update set updated_at=now()returning id into rid;return jsonb_build_object('ready',true,'id',rid,'status','VALIDADO');end$$;

create or replace function consolidation_translate(p_run bigint)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare r consolidation_runs%rowtype;rec record;rtype text;rate numeric;begin if not consolidation_has_permission('ACC_CONSOLIDATION_RUN')then raise exception'No tiene permiso para ejecutar consolidaciones.';end if;select*into r from consolidation_runs where id=p_run for update;if r.status='PUBLICADO'then raise exception'La consolidación publicada es inmutable.';end if;delete from consolidation_worksheet where run_id=p_run;for rec in select g.subsidiary_id,g.account_id,s.currency_id,coalesce(a.category,ag.category,'')category,sum(g.debit_amount-g.credit_amount)balance from gl_impact g join subsidiaries s using(subsidiary_id)join chart_accounts a using(account_id)left join account_group ag on ag.group_id=a.account_group_id where to_char(g.posting_date,'YYYY-MM')=r.period group by g.subsidiary_id,g.account_id,s.currency_id,a.category,ag.category loop if rec.currency_id=r.presentation_currency_id then rtype:='IDENTIDAD';rate:=1;elsif rec.category in('Activo','Pasivo')then rtype:='CIERRE';select closing_rate into rate from consolidated_exchange_rates where source_subsidiary_id=rec.subsidiary_id and period=r.period;elsif rec.category in('Ingreso','Costo','Gasto')then rtype:='PROMEDIO';select average_rate into rate from consolidated_exchange_rates where source_subsidiary_id=rec.subsidiary_id and period=r.period;else rtype:='HISTORICA';select historical_rate into rate from consolidated_exchange_rates where source_subsidiary_id=rec.subsidiary_id and period=r.period;end if;if rate is null then raise exception'Falta tasa para subsidiaria %.',rec.subsidiary_id;end if;insert into consolidation_worksheet(run_id,subsidiary_id,account_id,original_balance,original_currency_id,rate_type,applied_rate,translated_balance,final_balance)values(p_run,rec.subsidiary_id,rec.account_id,rec.balance,rec.currency_id,rtype,rate,round(rec.balance*rate,4),round(rec.balance*rate,4));end loop;update consolidation_runs set status='CONVERTIDO',updated_at=now()where id=p_run;return jsonb_build_object('id',p_run,'status','CONVERTIDO','rows',(select count(*)from consolidation_worksheet where run_id=p_run));end$$;

create or replace function consolidation_process(p_run bigint)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare assets numeric;liabilities numeric;equity numeric;result numeric;cta numeric;begin select coalesce(sum(case when coalesce(a.category,ag.category)='Activo'then w.final_balance else 0 end),0),coalesce(-sum(case when coalesce(a.category,ag.category)='Pasivo'then w.final_balance else 0 end),0),coalesce(-sum(case when coalesce(a.category,ag.category)='Patrimonio'then w.final_balance else 0 end),0),coalesce(-sum(case when coalesce(a.category,ag.category)in('Ingreso','Costo','Gasto')then w.final_balance else 0 end),0)into assets,liabilities,equity,result from consolidation_worksheet w join chart_accounts a using(account_id)left join account_group ag on ag.group_id=a.account_group_id where run_id=p_run;cta:=round(assets-liabilities-equity-result,4);update consolidation_runs set status='PROCESADO',total_assets=assets,total_liabilities=liabilities,total_equity=equity,cta_oci=cta,updated_at=now()where id=p_run;return jsonb_build_object('id',p_run,'status','PROCESADO','assets',assets,'liabilities',liabilities,'equity',equity,'result',result,'cta',cta);end$$;

create or replace function consolidation_worksheet_data(p_run bigint)returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('run',(select to_jsonb(r)from consolidation_runs r where id=p_run),'subsidiaries',coalesce((select jsonb_agg(distinct jsonb_build_object('id',s.subsidiary_id,'name',s.name))from consolidation_worksheet w join subsidiaries s using(subsidiary_id)where run_id=p_run),'[]'),'rows',coalesce((select jsonb_agg(x order by x->>'code')from(select jsonb_build_object('accountId',a.account_id,'code',a.account_number,'name',a.account_name,'companies',jsonb_object_agg(w.subsidiary_id,w.translated_balance),'summed',sum(w.translated_balance),'eliminationDebit',sum(w.elimination_debit),'eliminationCredit',sum(w.elimination_credit),'consolidated',sum(w.final_balance))x from consolidation_worksheet w join chart_accounts a using(account_id)where run_id=p_run group by a.account_id,a.account_number,a.account_name)q),'[]'))$$;
create or replace function consolidation_publish(p_run bigint)returns jsonb language plpgsql security definer set search_path=public as $$begin if not consolidation_has_permission('ACC_CONSOLIDATION_PUBLISH')then raise exception'No tiene permiso para publicar consolidaciones.';end if;update consolidation_runs set status='PUBLICADO',published_at=now(),updated_at=now()where id=p_run and status='PROCESADO';if not found then raise exception'Solo puede publicar una consolidación procesada.';end if;return jsonb_build_object('id',p_run,'status','PUBLICADO');end$$;
grant execute on function consolidation_options(),consolidation_init(varchar),consolidation_translate(bigint),consolidation_process(bigint),consolidation_worksheet_data(bigint),consolidation_publish(bigint)to authenticated,service_role;
